contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // run takes an amount to deposit into c from this contract
    function run(uint deposit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (deposit)); require(deposit <= 1000000000000000000000000000000);
        require(address(this).balance >= deposit, "insufficient balance in test");

        // Ensure there is some recorded balance for this test contract by depositing first.
        bool depReverted;
        c.addToBalance{value: deposit}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            depReverted = true;
        } else {
            depReverted = false;
        }

        // Record observable state before attempting withdrawal
        uint beforeUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;

        // Attempt to withdraw and catch whether it reverted
        bool withReverted;
        c.withdrawBalance(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            withReverted = true;
        } else {
            withReverted = false;
        }

        uint afterUser = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint afterContractBalance = address(c).balance;

        // General invariant: after withdrawBalance() either it reverted (so balances may be unchanged)
        // or it succeeded, in which case the contract's recorded balance for this caller is zero
        // and the contract's Ether balance did not increase (it should have decreased or stayed same).
        assert(
            withReverted
            ? true
            : (afterUser == 0 && afterContractBalance <= beforeContractBalance)
        );
    }

    // allow receiving Ether so this contract can fund deposits and receive refunds
    receive() external payable {}
}

