// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 deposit) internal {
        deposit = bound(deposit, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= deposit);
        bool depReverted;
        try c.addToBalance{value: deposit}() {
            depReverted = false;
        } catch {
            depReverted = true;
        }
        uint256 beforeUser;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeUser = __r; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        bool withReverted;
        try c.withdrawBalance() {
            withReverted = false;
        } catch {
            withReverted = true;
        }
        uint256 afterUser;
        try c.getBalance(address(this)) returns (uint256 __r) { afterUser = __r; } catch { return; }
        uint afterContractBalance = address(c).balance;
        assertTrue(withReverted
            ? true
            : (afterUser == 0 && afterContractBalance <= beforeContractBalance));
    }

    function testFuzz_run(uint256 deposit) public {
        _run(deposit);
    }

    receive() external payable {}
}
